ALTER TABLE "Lobby" ADD COLUMN "rulesConfig" jsonb;
ALTER TABLE "Lobby" DROP CONSTRAINT "Lobby_mode_rules_check";
ALTER TABLE "Lobby" ADD CONSTRAINT "Lobby_mode_rules_check" CHECK (("mode"='CLASSIC' AND "rulesetVersion"='CLASSIC_NLHE_V1' AND "rulesConfig" IS NULL) OR ("mode"='EVOLVED' AND "rulesetVersion"='EVOLVED_A_EXPERIMENTAL_V1' AND "rulesConfig" IS NULL) OR ("mode"='SPADES' AND "kind"='PRIVATE' AND "capacity"=4 AND COALESCE(jsonb_typeof("rulesConfig")='object' AND "rulesConfig"->'rules'->>'version'="rulesetVersion" AND jsonb_typeof("rulesConfig"->'approvalReference')='string',false)));
CREATE OR REPLACE FUNCTION lobby_rules_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW."mode"<>OLD."mode" OR NEW."rulesetVersion"<>OLD."rulesetVersion" OR NEW."rulesConfig" IS DISTINCT FROM OLD."rulesConfig") THEN RAISE EXCEPTION 'immutable lobby rules'; END IF; IF NEW."mode"='EVOLVED' AND NEW."status"='STARTED' THEN RAISE EXCEPTION 'evolved balance review required'; END IF; RETURN NEW; END $$;
CREATE TABLE "SpadesAdmission"("roomId" uuid PRIMARY KEY REFERENCES "SpadesRoom"("id") ON DELETE RESTRICT,"lobbyId" uuid NOT NULL REFERENCES "Lobby"("id") ON DELETE RESTRICT,"sequence" integer NOT NULL CHECK("sequence">0),"previousRoomId" uuid REFERENCES "SpadesRoom"("id") ON DELETE RESTRICT,"policySnapshot" jsonb NOT NULL,"createdAt" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(("sequence"=1)=("previousRoomId" IS NULL)));
CREATE UNIQUE INDEX "SpadesAdmission_lobbyId_sequence_key" ON "SpadesAdmission"("lobbyId","sequence");
CREATE UNIQUE INDEX "SpadesAdmission_lobbyId_previousRoomId_key" ON "SpadesAdmission"("lobbyId","previousRoomId");
CREATE TABLE "SpadesReservation"("roomId" uuid NOT NULL REFERENCES "SpadesRoom"("id") ON DELETE RESTRICT,"userId" uuid NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT,"items" jsonb NOT NULL CHECK(jsonb_typeof("items")='array' AND jsonb_array_length("items")=52),PRIMARY KEY("roomId","userId"),FOREIGN KEY("roomId","userId") REFERENCES "SpadesSeat"("roomId","userId") ON DELETE RESTRICT);
CREATE TABLE "TableMessage"("id" uuid PRIMARY KEY,"lobbyId" uuid NOT NULL REFERENCES "Lobby"("id") ON DELETE RESTRICT,"actorUserId" uuid NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT,"seat" integer NOT NULL CHECK("seat" BETWEEN 0 AND 3),"code" text NOT NULL CHECK("code" IN ('HELLO','THANKS','WELL_PLAYED','GOOD_GAME')),"createdAt" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "TableMessage_lobbyId_createdAt_idx" ON "TableMessage"("lobbyId","createdAt");
CREATE INDEX "TableMessage_actorUserId_createdAt_idx" ON "TableMessage"("actorUserId","createdAt");
CREATE TRIGGER spades_admission_immutable BEFORE UPDATE OR DELETE ON "SpadesAdmission" FOR EACH ROW EXECUTE FUNCTION spades_immutable();
CREATE TRIGGER spades_reservation_immutable BEFORE UPDATE OR DELETE ON "SpadesReservation" FOR EACH ROW EXECUTE FUNCTION spades_immutable();
CREATE TRIGGER table_message_immutable BEFORE UPDATE OR DELETE ON "TableMessage" FOR EACH ROW EXECUTE FUNCTION spades_immutable();
CREATE FUNCTION spades_reservation_consistent() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE rid uuid; a "SpadesAdmission"; r "SpadesRoom"; l "Lobby"; BEGIN
 IF TG_TABLE_NAME='SpadesRoom' THEN rid:=NEW."id"; ELSE rid:=NEW."roomId"; END IF;
 SELECT * INTO a FROM "SpadesAdmission" WHERE "roomId"=rid; IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO r FROM "SpadesRoom" WHERE "id"=rid; SELECT * INTO l FROM "Lobby" WHERE "id"=a."lobbyId";
 IF l."mode"<>'SPADES' OR a."policySnapshot" IS DISTINCT FROM l."rulesConfig" OR r."initial"->'rules' IS DISTINCT FROM a."policySnapshot"->'rules' OR (SELECT count(*) FROM "SpadesReservation" WHERE "roomId"=rid)<>4 THEN RAISE EXCEPTION 'invalid Spades admission'; END IF;
 IF a."previousRoomId" IS NOT NULL AND (NOT EXISTS(SELECT 1 FROM "SpadesAdmission" p JOIN "SpadesResult" pr ON pr."roomId"=p."roomId" WHERE p."lobbyId"=a."lobbyId" AND p."roomId"=a."previousRoomId" AND p."sequence"=a."sequence"-1) OR EXISTS(SELECT 1 FROM "SpadesSeat" s WHERE s."roomId"=rid AND NOT EXISTS(SELECT 1 FROM "SpadesSeat" p WHERE p."roomId"=a."previousRoomId" AND p."seat"=s."seat" AND p."userId"=s."userId"))) THEN RAISE EXCEPTION 'invalid Spades rematch'; END IF;
 IF EXISTS(SELECT 1 FROM "SpadesReservation" sr WHERE sr."roomId"=rid AND ((SELECT count(DISTINCT x->>'instanceId') FROM jsonb_array_elements(sr."items") x)<>52 OR EXISTS(SELECT 1 FROM jsonb_array_elements(sr."items") x LEFT JOIN "CardInstance" c ON c."id"=(x->>'instanceId')::uuid WHERE c."ownerId" IS DISTINCT FROM sr."userId" OR (r."phase"<>'MATCH_COMPLETE' AND (c."status"<>'LOCKED' OR c."lockToken" IS DISTINCT FROM rid OR c."stateVersion"<>(x->>'stateVersion')::integer)) OR (r."phase"='MATCH_COMPLETE' AND c."lockToken"=rid)))) THEN RAISE EXCEPTION 'invalid Spades inventory reservation'; END IF;
 IF r."phase"<>'MATCH_COMPLETE' AND (l."status"<>'STARTED' OR EXISTS(SELECT 1 FROM "SpadesSeat" s WHERE s."roomId"=rid AND NOT EXISTS(SELECT 1 FROM "LobbySeat" ls WHERE ls."lobbyId"=l."id" AND ls."userId"=s."userId" AND ls."seat"=s."seat"))) THEN RAISE EXCEPTION 'invalid active Spades roster'; END IF; RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER spades_admission_consistent AFTER INSERT ON "SpadesAdmission" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION spades_reservation_consistent();
CREATE CONSTRAINT TRIGGER spades_inventory_consistent AFTER INSERT ON "SpadesReservation" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION spades_reservation_consistent();
CREATE CONSTRAINT TRIGGER spades_completion_inventory AFTER UPDATE ON "SpadesRoom" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION spades_reservation_consistent();
CREATE FUNCTION spades_card_reserved() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD."lockReason"='SPADES_MATCH' AND EXISTS(SELECT 1 FROM "SpadesRoom" WHERE "id"=OLD."lockToken" AND "phase"<>'MATCH_COMPLETE') AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'active Spades inventory reserved'; END IF; RETURN NEW; END $$;
CREATE TRIGGER spades_card_reserved BEFORE UPDATE ON "CardInstance" FOR EACH ROW EXECUTE FUNCTION spades_card_reserved();

CREATE FUNCTION spades_lobby_consistent() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE phase text; BEGIN IF NEW."mode"<>'SPADES' THEN RETURN NULL; END IF; SELECT r."phase" INTO phase FROM "SpadesAdmission" a JOIN "SpadesRoom" r ON r."id"=a."roomId" WHERE a."lobbyId"=NEW."id" ORDER BY a."sequence" DESC LIMIT 1; IF (NEW."status"='STARTED') IS DISTINCT FROM (COALESCE(phase IN ('BIDDING','PLAYING','ROUND_COMPLETE'),false)) THEN RAISE EXCEPTION 'inconsistent Spades lobby lifecycle'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER spades_lobby_consistent AFTER INSERT OR UPDATE ON "Lobby" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION spades_lobby_consistent();
CREATE FUNCTION table_message_member() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM "LobbySeat" s JOIN "Lobby" l ON l."id"=s."lobbyId" WHERE s."lobbyId"=NEW."lobbyId" AND s."userId"=NEW."actorUserId" AND s."seat"=NEW."seat" AND l."mode"='SPADES' AND l."status"<>'CLOSED') THEN RAISE EXCEPTION 'invalid table message member'; END IF; RETURN NEW; END $$;
CREATE TRIGGER table_message_member BEFORE INSERT ON "TableMessage" FOR EACH ROW EXECUTE FUNCTION table_message_member();
